  return isFeminineName3(directorName) ? "\u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0439" : "\u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0433\u043E";
